module DominoMinSum(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] grid [0:3][0:3],\n    input [3:0] K,\n    output reg [15:0] min_sum,\n    output reg done\n);\n\n    // State encoding\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] RESET = 2'd1;\n    localparam [1:0] PROCESS_ROW = 2'd2;\n    localparam [1:0] DONE = 2'd3;\n\n    reg [1:0] state;\n    reg [3:0] row_counter;\n    reg [15:0] dp [0:15][0:8];\n    reg [15:0] dp_next [0:15][0:8];\n    reg [15:0] total_sum;\n    reg [15:0] best_covered;\n    integer i, j, m, k, s;\n\n    // Precomputed patterns (simplified for synthesis)\n    reg [0:0] pat_valid [0:4095];\n    reg [3:0] pat_new_mask [0:4095];\n    reg [3:0] pat_cur_cover [0:4095];\n    reg [2:0] pat_num_dom [0:4095];\n\n    // Initialize patterns (simplified)\n    initial begin\n        for (i = 0; i < 4096; i = i + 1) begin\n            pat_valid[i] = 1'b0;\n            pat_new_mask[i] = 4'd0;\n            pat_cur_cover[i] = 4'd0;\n            pat_num_dom[i] = 3'd0;\n        end\n        // Example pattern: place one horizontal domino\n        pat_valid[0] = 1'b1;\n        pat_new_mask[0] = 4'd3;  // 0011\n        pat_cur_cover[0] = 4'd3; // 0011\n        pat_num_dom[0] = 3'd1;\n        // Add more patterns as needed\n    end\n\n    // Compute total sum\n    function [15:0] compute_total_sum;\n        begin\n            compute_total_sum = 16'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                for (j = 0; j < 4; j = j + 1) begin\n                    compute_total_sum = compute_total_sum + grid[i][j];\n                end\n            end\n        end\n    endfunction\n\n    // Process one row\n    task process_row(input [3:0] r);\n        begin\n            // Initialize dp_next\n            for (m = 0; m < 16; m = m + 1) begin\n                for (k = 0; k <= 8; k = k + 1) begin\n                    dp_next[m][k] = 16'hFFFF;\n                end\n            end\n            // Iterate over masks and k\n            for (m = 0; m < 16; m = m + 1) begin\n                for (k = 0; k <= 8; k = k + 1) begin\n                    if (dp[m][k] != 16'hFFFF) begin\n                        for (s = 0; s < 128; s = s + 1) begin\n                            if (pat_valid[m*128 + s]) begin\n                                if (k + pat_num_dom[m*128 + s] <= K) begin\n                                    // Compute added weight\n                                    reg [15:0] added_weight = 16'd0;\n                                    for (j = 0; j < 4; j = j + 1) begin\n                                        if (pat_cur_cover[m*128 + s][j]) begin\n                                            added_weight = added_weight + grid[r][j];\n                                        end\n                                    end\n                                    if (r < 3) begin\n                                        for (j = 0; j < 4; j = j + 1) begin\n                                            if (pat_new_mask[m*128 + s][j]) begin\n                                                added_weight = added_weight + grid[r+1][j];\n                                            end\n                                        end\n                                    end\n                                    // Update dp_next\n                                    if (dp[m][k] + added_weight > dp_next[pat_new_mask[m*128 + s]][k + pat_num_dom[m*128 + s]]) begin\n                                        dp_next[pat_new_mask[m*128 + s]][k + pat_num_dom[m*128 + s]] = dp[m][k] + added_weight;\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n            // Copy dp_next to dp\n            for (m = 0; m < 16; m = m + 1) begin\n                for (k = 0; k <= 8; k = k + 1) begin\n                    dp[m][k] <= dp_next[m][k];\n                end\n            end\n        end\n    endtask\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            min_sum <= 16'd0;\n            row_counter <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        // Initialize DP\n                        for (m = 0; m < 16; m = m + 1) begin\n                            for (k = 0; k <= 8; k = k + 1) begin\n                                dp[m][k] <= 16'hFFFF;\n                            end\n                        end\n                        dp[0][0] <= 16'd0;\n                        row_counter <= 4'd0;\n                        state <= RESET;\n                    end\n                end\n                RESET: begin\n                    total_sum <= compute_total_sum();\n                    state <= PROCESS_ROW;\n                end\n                PROCESS_ROW: begin\n                    if (row_counter < 4) begin\n                        process_row(row_counter);\n                        row_counter <= row_counter + 4'd1;\n                    end else begin\n                        // Find best covered sum\n                        best_covered <= 16'd0;\n                        for (m = 0; m < 16; m = m + 1) begin\n                            if (dp[m][K] != 16'hFFFF && dp[m][K] > best_covered) begin\n                                best_covered <= dp[m][K];\n                            end\n                        end\n                        min_sum <= total_sum - best_covered;\n                        done <= 1'b1;\n                        state <= DONE;\n                    end\n                end\n                DONE: begin\n                    // Hold output\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule